const reverseGeocode = (lat, lng) => {
  // Calls external API to convert coordinates to address
  return fetch(`https://geocoding.example.com/reverse?lat=${lat}&lng=${lng}`)
    .then(response => response.json())
    .then(data => data.address);
};

const isUserInZone = async (coordinates) => {
  const address = await reverseGeocode(coordinates.latitude, coordinates.longitude);
  return address.city === 'San Francisco'; // Simplified check for demo
};

export { isUserInZone };"}]

